#!/usr/bin/env python3
"""穷举验证糖果题：最大失败集合 + 1 = 保证成功的最少取糖数。"""
from itertools import product

# (口味, 形状) -> 数量
CNT = {
    ("apple", "circle"): 7, ("peach", "circle"): 9, ("melon", "circle"): 8,
    ("apple", "star"): 7,   ("peach", "star"): 6,   ("melon", "star"): 4,
}
KEYS = list(CNT)
print("总糖数:", sum(CNT.values()))


def satisfied(h):
    """(圆苹果 & 星桃子) 或 (圆桃子 & 星苹果)"""
    ca, sp = h[("apple", "circle")], h[("peach", "star")]
    cp, sa = h[("peach", "circle")], h[("apple", "star")]
    return (ca >= 1 and sp >= 1) or (cp >= 1 and sa >= 1)


best, arg = -1, None
for combo in product(*(range(CNT[k] + 1) for k in KEYS)):
    hand = dict(zip(KEYS, combo))
    if not satisfied(hand):
        total = sum(combo)
        if total > best:
            best, arg = total, dict(hand)

print("最大失败集合:", best, "->", {k: v for k, v in arg.items() if v})
print("保证成功的最少取糖数:", best + 1)

#!/usr/bin/env python3
"""验证糖果题的两种读法。

关键在题干那句"不同的形状靠手感可以分辨"：摸糖时形状可以自己挑，口味不能挑。
于是参赛者事先决定"取 a 个圆形 + b 个五角星形"，最坏情况下的口味分配由对手决定。
"""
from itertools import product

CIRCLE = {"apple": 7, "peach": 9, "melon": 8}   # 24
STAR = {"apple": 7, "peach": 6, "melon": 4}     # 17


def splits(pool, n):
    """把 n 个名额分配到各口味，不超过库存。"""
    flavors = list(pool)
    for combo in product(*(range(pool[f] + 1) for f in flavors)):
        if sum(combo) == n:
            yield dict(zip(flavors, combo))


def ok(c, s):
    return (c["apple"] >= 1 and s["peach"] >= 1) or (c["peach"] >= 1 and s["apple"] >= 1)


def guaranteed(a, b):
    """取 a 圆 + b 星，是否所有口味分配都满足条件。"""
    star_options = list(splits(STAR, b))
    if not star_options:
        return False
    for c in splits(CIRCLE, a):
        for s in star_options:
            if not ok(c, s):
                return False  # 对手找到反例
    return True


best = None
for total in range(2, 42):
    for a in range(min(total, 24) + 1):
        b = total - a
        if b > 17:
            continue
        if guaranteed(a, b):
            best = (total, a, b)
            break
    if best:
        break

print("读法一（不能挑形状，纯抽屉）           : 28 + 1 = 29")
print(f"读法二（靠手感挑形状，题干明示可分辨） : {best[0]}  策略 = 圆形 {best[1]} 个 + 五角星 {best[2]} 个")

# 展示为什么 21 是紧的：20 个时对手的反制
t, a, b = best
print(f"\n检查 {t-1} 个是否不够：")
for aa in range(min(t - 1, 24) + 1):
    bb = t - 1 - aa
    if bb <= 17 and guaranteed(aa, bb):
        print(f"  反例：圆 {aa} + 星 {bb} 竟然够 —— 结论有误")
        break
else:
    print(f"  {t-1} 个的所有形状配比都能被对手破解，故最少 {t} 个。")
